"""Offline preservation audit and explicit method decision. Never starts a run."""
import json,sys,datetime,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from p14.common import OUT,write,sha

def main():
 out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=False)
 old=json.load(open(OUT/'audit-v1/input-hashes.json'));changed=[p for p,h in old.items() if not (ROOT/p).is_file() or sha(ROOT/p)!=h]
 p11=json.load(open(OUT/'audit-v1/p11-score-chain.json'));p11bad=[]
 for r in p11:
  p=ROOT/'data/p11-20261025-formal'/r['id']/'run/flight.ulg';s=ROOT/'data/p11-20261026-analysis'/r['id']/'score/score.json'
  if sha(p)!=r['raw_sha256'] or sha(s)!=r['score_sha256']:p11bad.append(r['id'])
 freeze=json.load(open(ROOT/'data/p13-20261026-freeze/manifest.json'))['files'];drift=[p for p,h in freeze.items() if sha(ROOT/p)!=h]
 seal=json.load(open(OUT/'candidate-v1/candidate-seal.json'));candidate_drift=[p for p,h in seal['sources'].items() if sha(ROOT/p)!=h]
 protocol=json.load(open(OUT/'protocol-seal.json'));protocol_drift=[p for p,h in protocol['files'].items() if sha(ROOT/p)!=h]
 rows=[json.loads(l) for l in (ROOT/'data/p13-20261026-preparation/attempts.jsonl').read_text().splitlines()];starts=[r for r in rows if r['event']=='START_INTENT'];assert len(starts)==78
 histories={str(p.relative_to(ROOT)):sha(p) for p in (ROOT/'data').glob('p1*-*preparation*/attempts.jsonl')}
 preserve={'old_bound_inputs':len(old),'changed':changed,'P11_original_score_raw_changes':p11bad,'P13_frozen_checked':len(freeze),'P13_freeze_drift':drift,'candidate_drift':candidate_drift,'protocol_drift':protocol_drift,'P13_starts_still':78,'current_historic_ledger_hashes':histories,'new_SITL':0,'status':'PASS' if not(changed or p11bad or drift or candidate_drift or protocol_drift) else 'FAIL'}
 write(out/'preservation.json',preserve);assert preserve['status']=='PASS'
 raw={str(p.relative_to(ROOT)):{'sha256':sha(p),'bytes':p.stat().st_size,'git_ignored':subprocess.run(['git','check-ignore','-q',str(p.relative_to(ROOT))]).returncode==0} for p in OUT.rglob('*.npz')}
 assert all(v['git_ignored'] for v in raw.values());write(out/'derived-local-manifest.json',raw)
 write(out/'baseline-observation.json',{'assembled_now_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'not_a_backdated_disk_snapshot':True,'source':'actual first pwd/git status/git log command outputs in this task, then remote ls-remote; no dedicated on-disk dirty snapshot was written at start','local_and_remote_observed_at_start':'4e18dbcce39edd23c07347526ab0de4818fccb24','tracked_dirty_at_start':[], 'preexisting_untracked':['AGENTS.md','data/p11-20261026-analysis/publication-after-push.json','data/p11-20261026-analysis/publication-count-correction.json','data/p12-20261026-score-review/publication-receipt.json','data/p12-cont-20261026-publication-local.json','data/p12b-20261026-publication-local.json','data/p12c-20261026-publication-local.json','data/p13-20261026-publication-local.json','data/p9-20261024-preparation/attempts.lock'],'gitignore_change':'one added P14-derived NPZ pattern, old patterns unchanged; no raw/runtime upload'})
 evaluation=json.load(open(OUT/'evaluation-v1/summary.json'));write(out/'analysis-errata.json',{'theory_v1_preserved':'COM_L used cap-z in NED; v2 fixes z-cap and ordered bounds. Prediction/scoring unchanged.','old_A4_CLI_failure':'source dependency guard rejected current newer source; kept, not disabled; independent archived arithmetic matches original exactly','scorer_metadata_scope':'p12 scoring inherited text says no new predictions: scorer function does not predict. P14 generated new retrospective G/M14 outputs separately; candidate and risk are explicitly retrospective.','new_SITL':0})
 machine={'schema':'p14-method-feasibility-1','baseline':protocol['head'],'new_SITL':0,'launcher_calls':0,'budget_consumed':0,'offline_completion':'COMPLETE','engineering':'PASS_SCOPED_OFFLINE_REPLAY_AND_IDENTITY','new_experimental_validation':'NONE','all_new_scores':'RETROSPECTIVE','old_forward_scores':'UNCHANGED','P13_population':{'development':12,'formal':66,'independent_formal_seed_blocks':6},'baseline_exact_score_matches':evaluation['original_baseline_score_exact_models_matches'],'main_candidate':'M14','geometry_control':'G','formal_M14':evaluation['groups']['formal']['M14'],'method_risk_prediction':'NOT_RELIABLE_SAFETY_ADMISSION','theory':'CONDITIONAL_MAPS_AND_CORRELATED_REDUCED_SET_ONLY; first source angular extension not invariant','A4':'NOT_PROVEN_EXCLUDED','route':{'stop':['independent outer-box/nonnegative-absolute-gain whole-task guarantee','incorrect named-origin LP mapping','constant-bias/OR-only claims of model sufficiency'],'continue':['joint physical/body/IMU/estimator/cache/history time-process representation','short finite shared-generator reachability with angular/estimator closure','source solver arithmetic/mode certification']},'next_unique_question':'close body/IMU-to-attitude/gyro/LP/cache dynamics jointly with source angular process before expanding forecasts','minimal_future_diagnostic_proposal':{'executed':False,'budget_authorized_here':0,'starts_proposed_only_if_missing_internal_state_unrecoverable':6,'arms':['NORMAL','F4-A','F2-AB-short'],'seed_blocks':2,'purpose':'identifiability of initial output buffers/fusion state, not miss-rate assurance'},'tests':{'local_targeted':31,'status':'PASS','all_project_claim':False},'CI':'READ_AFTER_NORMAL_PUBLICATION','preservation':preserve['status'],'execution_denied_pending_uncertain':[],'remaining_proof_obligations':['actual future solver/matrix/FP/mode budgets','body/angular/estimator/cache/history joint reachable domain and intersample bounds','nonempty actual closed-loop membership of conditional recovery/repair domains']}
 write(out/'machine-conclusion.json',machine);write(out/'deliverable-hashes.json',{str(p.relative_to(ROOT)):sha(p) for p in list((ROOT/'docs').glob('THOR_P14*.md'))+list((ROOT/'tools/p14').glob('*.py'))+[ROOT/'config/p14-offline.json',ROOT/'tests/test_p14.py']})
 print('P14_FINAL_AUDIT',preserve['status'],len(old),'old inputs',len(freeze),'frozen files',len(raw),'local array files',flush=True)
if __name__=='__main__':main()
